insert into public.project_tasks(id,household_id,created_by,project_id,title) values ('22000300-0000-4000-8000-000000000099','22000100-0000-4000-8000-000000000002','22000000-0000-4000-8000-000000000003','22000200-0000-4000-8000-000000000002','Private task');
set local role authenticated; select set_config('request.jwt.claim.sub','22000000-0000-4000-8000-000000000001',true);
select is((select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000001", "title": "Pack chargers", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000002", "title": "Pack clothes", "section": "Packing", "notes": ""}]'))->>'added','2','selected tasks are added atomically');
select is((select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000001", "title": "Pack chargers", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000002", "title": "Pack clothes", "section": "Packing", "notes": ""}]'))->>'added','0','a lost-response retry adds no duplicates');
select is((select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000003", "title": "Pack chargers", "section": "Packing", "notes": ""}]'))->>'added','0','fresh requests skip an existing checklist task');
select is((select count(*) from public.project_tasks),2::bigint,'only two tasks exist');
update public.project_tasks set title='Changed after adding',completed_at=now() where id='22000300-0000-4000-8000-000000000001';
select is((select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000001", "title": "Pack chargers", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000002", "title": "Pack clothes", "section": "Packing", "notes": ""}]'))->>'added','0','replay does not replace edited or completed work');
select is((select title from public.project_tasks where id='22000300-0000-4000-8000-000000000001'),'Changed after adding','edited task remains unchanged');
select is((select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id":"22000300-0000-4000-8000-000000000003","title":"Pack chargers","section":"Packing","notes":""}]'))->>'added','0','previously skipped selection stays skipped after matched task is edited');
update public.project_tasks set archived_at=now() where id='22000300-0000-4000-8000-000000000001';
select is((select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id":"22000300-0000-4000-8000-000000000003","title":"Pack chargers","section":"Packing","notes":""}]'))->>'added','0','previously skipped selection stays skipped after matched task is archived');
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id":"22000300-0000-4000-8000-000000000003","title":"Changed request","section":"Packing","notes":""}]')$$,'22023',null,'selection identity is bound to its original payload');
select throws_ok($$select * from private.project_starter_selections$$,'42501',null,'receipt rows are not client readable');
select throws_ok($$delete from private.project_starter_selections$$,'42501',null,'receipt rows are not client mutable');
reset role;
select ok((select relrowsecurity from pg_class where oid='private.project_starter_selections'::regclass),'selection receipts have RLS');
set local role authenticated;
select set_config('request.jwt.claim.sub','22000000-0000-4000-8000-000000000002',true);
select is((select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000004", "title": "Pack passports", "section": "Packing", "notes": ""}]'))->>'added','1','partner has equal access');
select is((select created_by::text from public.project_tasks where id='22000300-0000-4000-8000-000000000004'),'22000000-0000-4000-8000-000000000002','batch uses the authenticated creator');
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[]')$$,'22023',null,'empty batch rejected');
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','null')$$,'22023',null,'non-array rejected');
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000100", "title": "Task 0", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000101", "title": "Task 1", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000102", "title": "Task 2", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000103", "title": "Task 3", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000104", "title": "Task 4", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000105", "title": "Task 5", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000106", "title": "Task 6", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000107", "title": "Task 7", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000108", "title": "Task 8", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000109", "title": "Task 9", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000110", "title": "Task 10", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000111", "title": "Task 11", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000112", "title": "Task 12", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000113", "title": "Task 13", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000114", "title": "Task 14", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000115", "title": "Task 15", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000116", "title": "Task 16", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000117", "title": "Task 17", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000118", "title": "Task 18", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000119", "title": "Task 19", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000120", "title": "Task 20", "section": "Packing", "notes": ""}]')$$,'22023',null,'oversized batch rejected');
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000005", "title": "Duplicate", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000005", "title": "Duplicate", "section": "Packing", "notes": ""}]')$$,'22023',null,'duplicate request IDs rejected');
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000006", "title": "Would be inserted", "section": "Packing", "notes": ""}, {"id": "22000300-0000-4000-8000-000000000007", "title": "", "section": "Packing", "notes": ""}]')$$,'22023',null,'invalid later item rolls back entire batch');
