select set_config('request.jwt.claim.sub','22000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000011", "title": "Outsider", "section": "Packing", "notes": ""}]')$$,'42501',null,'outsider cannot add tasks');
reset role; set local role anon; select set_config('request.jwt.claim.sub','',true);
select throws_ok($$select public.add_project_task_batch('22000200-0000-4000-8000-000000000001','[{"id": "22000300-0000-4000-8000-000000000012", "title": "Anonymous", "section": "Packing", "notes": ""}]')$$,'42501',null,'anonymous invocation denied');
reset role; select * from finish(); rollback;
